CAT = "cparegDeductions"; SEG = "DED"
Q = [
("Which item is a deduction for AGI rather than an itemized deduction?",
 "Half of self-employment tax", ["Home mortgage interest", "State income taxes", "Unreimbursed medical costs"],
 "The deductible half of self-employment tax is an adjustment to income. Mortgage interest, state taxes and medical costs are itemized deductions."),
("A self-employed individual with no employer plan available pays her own health insurance premiums. They are deductible:",
 "For AGI, up to SE earnings", ["Only as itemized medical", "Not at all", "Only above 7.5% of AGI"],
 "Self-employed health insurance is an adjustment to income, limited to the net earnings from the business, when no subsidized employer plan is available."),
("An eligible individual's own contributions to a health savings account, within the limit, are:",
 "Deductible for AGI", ["Deductible only if itemizing", "Never deductible", "A refundable credit"],
 "Contributions an eligible individual makes to an HSA are an above-the-line deduction, available whether or not the taxpayer itemizes."),
("A taxpayer with AGI of $60,000 has $7,000 of unreimbursed medical expenses and itemizes. The medical deduction is:",
 "$2,500", ["$7,000", "$1,000", "$4,500"],
 "Medical expenses are deductible above 7.5% of AGI: $7,000 - (7.5% x $60,000 = $4,500) = $2,500."),
("Which cost qualifies as a deductible medical expense?",
 "Prescription drugs", ["Over-the-counter vitamins", "Gym membership dues", "Cosmetic teeth whitening"],
 "Prescribed drugs and insulin qualify. General health items, gym dues and cosmetic procedures do not."),
("Which tax can an individual deduct as an itemized deduction?",
 "Real estate tax on a home", ["Federal income tax", "Employee FICA tax", "Federal gift tax paid"],
 "State and local real property taxes are deductible taxes, subject to the SALT limit. Federal income, FICA and gift taxes are never deductible."),
("Interest on a home equity loan whose proceeds paid off credit card debt is:",
 "Not deductible", ["Fully deductible", "Deductible up to 50%", "Deductible for AGI"],
 "Home equity interest is deductible only when the loan is used to buy, build or substantially improve the home. Paying off credit cards makes it personal interest."),
("After the $100 floor per event, a personal casualty loss is generally deductible only to the extent the total exceeds what share of AGI?",
 "10%", ["7.5%", "2%", "50%"],
 "Personal casualty losses that qualify are reduced by $100 per event and then by 10% of AGI. The 7.5% floor is for medical expenses."),
("The qualified business income deduction is generally 20% of QBI, limited to 20% of the taxpayer's:",
 "Taxable income less net capital gain", ["Adjusted gross income less losses", "W-2 wages paid by the business", "Gross receipts of the business"],
 "The overall cap is 20% of taxable income before the QBI deduction, reduced by net capital gain. W-2 wages matter only for the separate wage limit above the threshold."),
("Which item is excluded from qualified business income?",
 "Guaranteed payments to a partner", ["Sole proprietor's net profit", "S corporation ordinary income", "A rental business's net income"],
 "QBI excludes guaranteed payments, reasonable compensation, capital gains and most investment income. Ordinary business income from a qualified trade or business counts."),
("A single taxpayer has a $2,000 net short-term capital gain and a $9,000 net long-term capital loss. This year's deduction against ordinary income and the carryover are:",
 "$3,000; $4,000 carried over", ["$7,000; nothing carried over", "$3,000; $6,000 carried over", "$2,000; $5,000 carried over"],
 "Netting gives a $7,000 net capital loss. $3,000 offsets ordinary income and $4,000 carries forward as a long-term loss."),
("A married person filing a separate return may deduct a net capital loss against ordinary income of up to:",
 "$1,500", ["$3,000", "$1,000", "$750"],
 "The annual limit is $3,000, or $1,500 for married filing separately. Any excess carries forward indefinitely."),
("Ana materially participates in an S corporation. Her stock basis is $12,000, she has no debt basis, and her share of its loss is $20,000. Ignoring the at-risk and excess business loss limits, she may deduct:",
 "$12,000", ["$20,000", "$8,000", "$0"],
 "An S corporation shareholder deducts losses only up to stock and debt basis. The $8,000 not allowed carries forward until she has basis."),
("Hal actively participates in a rental property, has MAGI of $120,000, a $30,000 rental loss and no other passive income. He may deduct:",
 "$15,000", ["$25,000", "$30,000", "$10,000"],
 "The $25,000 rental allowance is cut by 50% of MAGI over $100,000: $25,000 - $10,000 = $15,000. The other $15,000 is suspended."),
("An activity is a hobby. It earns $4,000 and has $6,000 of expenses. The taxpayer reports:",
 "$4,000 income, no deduction", ["A $2,000 loss", "No income or loss", "$4,000 income and deduction"],
 "Hobby income is fully included, but hobby expenses are not deductible under current law, so there is no offset."),
("A taxpayer sells her personal car at a loss. The loss is:",
 "Not deductible", ["A capital loss", "An ordinary loss", "Deductible to $3,000"],
 "A loss on the sale of a personal-use asset is not deductible, even though a gain on the same asset would be taxable."),
("Mia buys 100 more shares of a stock on November 25, then on December 20 sells 100 older shares of it at a $2,000 loss. The loss is:",
 "Deferred into the new shares", ["Deductible this year", "Lost permanently", "Deductible next year"],
 "The wash sale window runs 30 days before and after the sale, so a purchase 25 days earlier counts. The loss is disallowed and added to the basis of the November shares."),
("Ed sells stock to his brother at a $3,000 loss. Ed's loss is:",
 "Disallowed", ["Fully deductible", "Deductible up to $1,500", "Deferred one year"],
 "Section 267 disallows losses on sales between related parties, including brothers. The brother may use it to reduce a later gain."),
("Interest paid on a qualified student loan is deducted:",
 "For AGI, up to a cap", ["As an itemized deduction", "As a nonrefundable credit", "Only by the borrower's parent"],
 "Student loan interest is an above-the-line deduction up to an annual cap, phased out at higher incomes."),
("A single taxpayer's traditional IRA contribution, within the annual limit, is fully deductible at any income level when the taxpayer:",
 "Is not in a workplace plan", ["Is under age 50", "Has no other income", "Itemizes deductions"],
 "The income phase-out applies only to taxpayers covered by an employer retirement plan. An uncovered single taxpayer deducts the full contribution."),
]
